<article class="card" data-type="{{ $o->category }}"><div class="img" style="background:{{ $o->color }}" aria-hidden="true">{{ $o->icon }}<img src="{{ asset('images/'.$o->image.'.jpg') }}" alt="" loading="lazy" onerror="this.remove()"></div><div class="body"><h3>{{ $o->title }}</h3><span class="tag">{{ $o->category }}</span><div class="meta"><span>📍 {{ $o->city }}</span><span>📅 {{ $o->event_date->format('Y-m-d') }}</span></div><p>{{ \Illuminate\Support\Str::limit($o->description, 90) }}</p><div class="progress" title="{{ $o->registeredCount() }} من {{ $o->capacity }}"><i style="width:{{ $o->percent }}%"></i></div><small>{{ $o->registeredCount() }} من {{ $o->capacity }} مسجّل</small> <a class="btn green sm" href="{{ route('opportunities.show', $o) }}">{{ ['open' => 'التفاصيل والتسجيل', 'full' => 'اكتمل العدد', 'closed' => 'انتهت الفرصة'][$o->status] }}</a></div></article>
